package kz.zeroops.agent;
import java.io.*; import java.nio.file.*; import java.util.*; import java.util.concurrent.TimeUnit; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component;
/** Explicit opt-in. No shell or user-supplied command is executed. */
@Component @ConditionalOnProperty(name="agent.execution-mode",havingValue="docker") class DockerDeploymentExecutor implements DeploymentExecutor { public ExecutionResult execute(AgentBoundary.Manifest m){Path dir=null;try{dir=Files.createTempDirectory("autodeploy-"+m.deploymentId()+"-");if(!run(List.of("git","clone","--depth","1","--branch",m.branch(),m.repositoryUrl(),dir.toString())))return new ExecutionResult(false,"Git checkout failed.","Git checkout failed");if(!run(List.of("git","-C",dir.toString(),"checkout","--detach",m.commitSha())))return new ExecutionResult(false,"Requested commit is unavailable.","Commit checkout failed");if(!run(List.of("docker","build","--pull","--tag",m.imageTag(),dir.toString())))return new ExecutionResult(false,"Docker image build failed.","Image build failed");String name="autodeploy-"+m.projectId()+"-"+m.deploymentId();boolean ok=run(List.of("docker","run","--detach","--rm","--name",name,"--label","io.autodeploy.managed=true","--label","io.autodeploy.project="+m.projectId(),"--read-only","--cap-drop","ALL","--security-opt","no-new-privileges","--pids-limit","256","--memory","512m","--cpus","1.0","--publish","127.0.0.1::"+m.applicationPort(),m.imageTag()));return ok?new ExecutionResult(true,"Immutable image built and isolated container started.",null):new ExecutionResult(false,"Docker rejected verified deployment.","Docker run failed");}catch(IOException e){return new ExecutionResult(false,"Agent workspace unavailable.","Workspace unavailable");}finally{if(dir!=null)try(var paths=Files.walk(dir)){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(IOException ignored){}});}catch(IOException ignored){}}} private boolean run(List<String> c){try{Process p=new ProcessBuilder(c).redirectErrorStream(true).start();if(!p.waitFor(10,TimeUnit.MINUTES)){p.destroyForcibly();return false;}return p.exitValue()==0;}catch(IOException e){return false;}catch(InterruptedException e){Thread.currentThread().interrupt();return false;}} }
